Can LoadSystemVars and loadSessionVarsInternal be extracted as member functions of any interface?
Then we can define a common function:
``` go
func loadSystemVars(ctx interface{}, sysVars map[string]string) error {
    sessionVars, err := newSessionVarsWithSystemVariables(sysVars)
    if err != nil {
        return err
    }
    ctx.loadSessionVarsInternal(sessionVars, sysVars)
    return nil
}

```
